rows=[]; journal=[]
def group(theme,code,title,url,ref,items):
 start=151+len(rows)
 for question,options,explanation in items:
  idx=len(rows)%4; rotated=options[-idx:]+options[:-idx] if idx else options
  rows.append(dict(id=f'q{151+len(rows):03}',theme=theme,question=question,options=rotated,correct=idx,explanation=explanation,code=code,topic='Géographie' if theme=='Géographie' else 'Histoire',sources=[dict(title='UNESCO · '+title,url=url)],verified='2026-11-15'))
 journal.append((start,150+len(rows),title,url,ref))
def g(code,title,num,ref,items):group('Géographie',code,title,f'https://whc.unesco.org/en/list/{num}/',ref,items)
def h(code,title,num,ref,items):group('Histoire',code,title,f'https://whc.unesco.org/en/list/{num}/',ref,items)
def c(code,title,slug,ref,items):group('Culture',code,title,'https://ich.unesco.org/'+slug,ref,items)
