base=OUT.parent
countries=json.load(open(base/'v14_work/Meridien/data/countries.json'))
old=json.load(open(base/'v14_work/Meridien/data/quiz.json'))
assert all(r['code'] in countries for r in rows)
assert len({r['question'] for r in rows+old})==len(rows+old)
assert all(len(set(r['options']))==4 for r in rows)
(OUT/'quiz_extra_a.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
report=['# Quiz V15 — lot A : 90 questions','', 'Vérification éditoriale : 15 novembre 2026. 30 Géographie, 30 Histoire, 30 Culture. '+str(len({r['code'] for r in rows}))+' pays distincts. Questions rédigées manuellement à partir de 30 notices institutionnelles UNESCO consultées; aucune génération en utilisation.', '', 'Les notices du patrimoine mondial ont été ouvertes. Certaines notices du patrimoine immatériel opposent un écran anti-robot à l’ouverture : leur contenu indexé a été consulté par recherche; les références de consultation sont consignées ci-dessous. Il ne s’agit pas d’un contrôle indépendant par plusieurs historiens. Les sources sont primaires pour les inscriptions patrimoniales et des synthèses institutionnelles pour leurs contenus historiques.', '', 'Contrôles : 90 identifiants uniques q151–q240, quatre réponses distinctes, indice valide, codes pays existants, équilibre thématique 30/30/30. Comparaison au catalogue V14 pour éviter les mêmes faits; relecture des thèmes existants. Liens vers les rubriques Histoire/Géographie, pas promesse que chaque détail figure dans le texte de la fiche.', '', 'Limites éditoriales : trois questions distinctes par notice; elles pourront apparaître éloignées par le sélecteur quotidien. Les affirmations fragiles des sources ont été écartées (date précise de naissance du Bouddha, jour exact de l’éruption de 79, ancienneté linguistique du sanskrit, superlatifs glaciaires, données de population). Les pratiques rituelles ne constituent pas des recommandations médicales.', '', '| Questions | Notice | Consultation |', '|---|---|---|']
for start,end,title,url,ref in journal:report.append(f'| q{start}–q{end} | [{title}]({url}) | {ref} |')
report+=['','Budget par source : trois questions originales et explications courtes; contrôle automatique de tous les mots affichés pour chaque groupe ci-dessous. Aucun extrait long copié.']
for start,end,title,url,ref in journal:
 subset=rows[start-151:end-150]
 words=sum(len(re.findall(r"\S+",r['question']+' '+' '.join(r['options'])+' '+r['explanation'])) for r in subset)
 report.append(f'- {title} : {words} mots (y compris distracteurs).')
 assert words<=200,(title,words)
(OUT/'quiz_extra_a_sources.md').write_text('\n'.join(report)+'\n')
print('OK',len(rows),len({r['code'] for r in rows}),collections.Counter(r['theme'] for r in rows))
